// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        bool reverted;
        try c.withdrawAll(payable(address(this))) { reverted = false; } catch { reverted = true; }
        assertTrue(caller != address(0) ? reverted == false : true);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable { }
}
